{"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕（约7500字，占比25%）：建立高三校园规则世界观，引入苏晚被霸凌的现状，她为躲避霸凌躲进监控死角触发规则，变成透明人后看见失踪三年的陈屿，两人终于能够交流。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "监控死角的三分钟",
        "core_event": "苏晚被张琪堵在走廊霸凌，逃到实验楼后楼梯的监控死角，停留超过三分钟后身体逐渐变透明，进入半透明的灰色透明层，看见了穿着三年前校服的陈屿。",
        "emotional_tone": "慌乱、诧异、不敢置信",
        "key_scenes": ["走廊被张琪等人堵截霸凌", "慌不择路逃进实验楼后楼梯监控死角", "身体慢慢变得透明，周围世界变成灰色半透明", "抬头看见站在楼梯转角的陈屿"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "耳边说了三年的声音",
        "core_event": "陈屿发现苏晚能看见自己十分震惊，两人交流后苏晚得知陈屿已经被困在透明层三年，并且这三年里一直在她耳边说话，她之前却完全听不到，同时苏晚想起透明状态只有24小时，时效到后会忘记所有相关记忆。",
        "emotional_tone": "震惊、酸涩、荒谬感",
        "key_scenes": ["陈屿开口说话苏晚清晰听见", "两人核对身份确认对方就是记忆里的人", "陈屿说自己这三年一直跟着苏晚说话", "苏晚想起规则的24小时时效和遗忘代价"]
      }
    ],
    "turning_point": "苏晚确认自己真的能看见失踪三年的陈屿，同时知晓两人只有24小时的相处时间，之后她会彻底忘记这一切。"
  },
  "act_two": {
    "description": "第二幕（约15000字，占比50%）：两人在透明层共同度过大部分时间，陈屿带苏晚看他这三年的足迹，说出他记录的关于苏晚的所有小事，苏晚逐渐察觉陈屿的心意，最终发现他是为了救自己才被困三年的真相，陷入巨大的愧疚。",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "透明层的三年足迹",
        "core_event": "陈屿带着苏晚逛遍整个校园的透明层，告诉她这三年里他每天看着她上下学、刷题、被霸凌，说出很多苏晚自己都没注意过的小习惯，苏晚逐渐感受到陈屿藏了很久的心意，双向暗恋的氛围逐渐升温。",
        "emotional_tone": "温暖、酸涩、小心翼翼的甜蜜",
        "key_scenes": ["逛操场透明层看日落", "站在高三教室外看苏晚平时的座位", "陈屿说他记录的苏晚的小习惯（咬笔、喜欢买橘子味汽水）", "两人靠在栏杆上聊过去的事"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "未说出口的牺牲",
        "core_event": "两人回到实验楼后楼梯，苏晚想起三年前同样被张琪霸凌逃到这里的经历，追问陈屿当年为什么会出现在这里，陈屿不得不承认自己当年是为了引开张琪才故意跑进监控死角触发规则，把自己困在这里三年。苏晚崩溃大哭，背负上沉重的愧疚感。",
        "emotional_tone": "痛苦、愧疚、心碎",
        "key_scenes": ["苏晚回忆起三年前被霸凌的细节", "反复追问陈屿当年失踪的原因", "陈屿坦白是为了救她才故意触发规则", "苏晚崩溃大哭，反复说对不起"]
      }
    ],
    "turning_point": "苏晚知晓陈屿为救自己被困三年的真相，愧疚感淹没了所有甜蜜，两人的关系从双向奔赴的喜悦变成背负着沉重代价的痛苦。"
  },
  "act_three": {
    "description": "第三幕（约7500字，占比25%）：只剩最后几个小时，两人互相告白，尝试留下记忆的痕迹却被规则抹除，24小时时效到后苏晚彻底遗忘一切，回到正常生活，只留下一个空落落的缺口，陈屿依旧被困在透明层里，再也不会有人能看见他。",
    "key_chapters": [
      {
        "chapter_number": 5,
        "chapter_title": "最后三小时的约定",
        "core_event": "两人只剩下最后三小时，苏晚拼命想要把陈屿的脸和声音刻进脑子里，互相说出藏了三年的暗恋心意，尝试写纸条、拍照片留下记录，却发现所有痕迹都会被规则自动抹除。最后一分钟两人尝试拥抱，却只能穿过彼此的身体。",
        "emotional_tone": "绝望、浓烈的爱意、无力感",
        "key_scenes": ["互相告白，说出藏了三年的心意", "尝试在笔记本上写陈屿的名字，字迹自动消失", "用手机拍照，相册里一片空白", "最后一分钟的虚拟拥抱，指尖穿过彼此的身体"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "风会记得他的名字",
        "core_event": "24小时时效到，苏晚在教室醒来完全忘记前一天的事，只觉得心里空落落的，好像丢了什么重要的东西。她路过实验楼后楼梯的时候下意识停顿，却什么都没想起。陈屿站在透明层里看着她的背影，轻轻说我喜欢你，风把声音吹过苏晚耳边，她疑惑回头却什么都没看见，转身走了。",
        "emotional_tone": "极致虐心、遗憾、余韵悠长的BE",
        "key_scenes": ["苏晚在早自习的喧闹中醒来，完全忘记前一天的事", "摸口袋里的空白笔记本，觉得莫名熟悉", "路过实验楼后楼梯下意识停下脚步", "陈屿的告白被风吹过苏晚耳边，她回头却什么都没看见，转身离开"]
      }
    ]
  }
}"}

